from pathlib import Path
p=Path('products/services/tender-instant-preview')
if not p.exists():
 print('No published instant-preview evidence exists in the selected input. Implementation or completion is not established.')
else:
 files=sorted(x for x in p.rglob('*') if x.is_file())
 for f in files: print(str(f),f.stat().st_size)
 budget=30000
 for f in files:
  if f.suffix=='.json':
   s=f.read_text(encoding='utf-8')
   if len(s.encode('utf-8'))<=budget:
    print('\nFILE '+str(f)+'\n'+s)
    budget-=len(s.encode('utf-8'))
   else: print('NOT READ: exceeds remaining inspection budget: '+str(f))
